mapper.select:
/* selectMasterMdCdBuyerCardSearchList */ SELECT DT.BUYER , GETCMSLOCNAME(HD.BUYER, HD.SITE) AS COM_NAME_LOC , DT.VISIT_TYPE , (SELECT COD.TEXT1 FROM ICOMCOD1 COD WHERE COD.TYPE ='K003' AND COD.CODE = DT.VISIT_TYPE) AS VISIT_TEXT , DT.ADD_USER_ID , (SELECT USR.USER_NAME_LOC FROM ICOMLUSR USR WHERE USR.USER_ID = DT.ADD_USER_ID) AS ADD_DUSER_NM , TO_CHAR(TO_DATE(VISIT_DATE||VISIT_TIME,'YYYYMMDDHH24MISS'),'YYYY-MM-DD HH24:MI') VISIT_DATE , SUBSTR(VISIT_NOTE,0,50) AS VISIT_NOTE , DT.IMAGE_KEY , DECODE(DT.IMAGE_KEY, NULL, '2', '1') AS IMAGE_KEY_IMG ,(SELECT DEPARTMENT FROM ICOMLUSR WHERE USER_ID = DT.ADD_USER_ID) AS DEPARTMENT , DT.ADD_DATE , DT.ADD_TIME FROM KEP_VISITDT DT, KEP_VISITHD HD WHERE 1=1 AND DT.STATUS <> 'D' AND DT.VISIT_DATE BETWEEN #{st_from_date} AND #{st_to_date} AND DT.BUYER = HD.BUYER
AND DT.VISIT_TYPE = #{st_visit_kind}
AND DT.ADD_USER_ID = #{st_kep_user_id}
AND DT.VISIT_NOTE LIKE '%' || #{st_visit_note} || '%'
AND DT.BUYER IN
#{item}
ORDER BY GETCMSLOCNAME(HD.BUYER, HD.SITE), DT.VISIT_DATE
